-- BCOH2H-849: standalone English database comments; run on the HTH_BEA connection.
-- DBeaver: open this entire file and Execute SQL Script (Alt+X).
-- Requires HTH_BEA.HTH_CRM_EVENT_DETAILS and the 113 columns installed by script 1.
-- No table/column/index definition or business data is changed. Repeat execution is safe.
-- Oracle COMMENT statements commit implicitly; use a dedicated deployment session.
-- Stop on errors. ORA-00904 indicates a missing column: finish script 1 before retrying.
-- Extra legacy columns and HTH_MTB_API_CONFIG are outside this script's scope.
-- Successful execution sets one table comment and 113 column comments; no restart is required.

COMMENT ON TABLE HTH_BEA.HTH_CRM_EVENT_DETAILS IS 'HTH CM/BM onboarding operation records for CRM/MTB; populated by application events, with no deployment seed data.';

COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.EVENT_ID IS 'Unique event identifier generated by the HTH CRM collector.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.RECORD_TYPE IS 'CRM record type from the existing BCO CRM configuration; null when not configured.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.FILLER_01 IS 'CRM filler value from the existing BCO CRM configuration; null when not configured.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.EVENT_DTE IS 'Event date in Asia/Hong_Kong time, formatted as yyyyMMdd.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.EVENT_TIME IS 'Event time in Asia/Hong_Kong time, formatted as HHmmss.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.CHNL_ID IS 'BCO CRM channel identifier from Login-Channel and CRM configuration; distinct from the CM/BM portal.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.CHNL_TYPE_CODE IS 'BCO CRM channel type code from the existing CRM configuration; null when not configured.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.EVENT_STATUS_CODE IS 'Operation-stage result: A for success or submission accepted for approval; R for failure or business rollback.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.CR_DR_IND IS 'Credit or debit indicator from the BCO model; reserved and null for current HTH CM/BM onboarding events.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.FEE_CHRG_CODE IS 'Fee charge classification from the existing BCO CRM configuration; no fee is generated by this record.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.EVENT_ACTV_TYPE_CODE IS 'External CRM activity code from ACTIVITY_<ACTIVITY_KEY> configuration; null when not configured.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.FIN_IND IS 'Financial indicator; N for the non-financial CM/BM onboarding operations in this release.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.SELF_SRV_IND IS 'BCO self-service indicator derived from the platform isAdmin context; null when unknown.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.USER_ID IS 'User who performed this operation or approval action.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.EVENT_COUNTRY_CODE IS 'CRM event country code from the existing BCO CRM configuration; null when not configured.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.ACCT_NBR IS 'Corporate party identifier for the maintenance operation; not an individual bank account number.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.PHONE_NBR IS 'Phone proxy number from the BCO model; reserved and null for current HTH CM/BM onboarding events.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.PHONE_NBR_ACCT_NBR IS 'Account linked to the phone proxy from the BCO model; reserved and null for current HTH CM/BM onboarding events.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.PHONE_NBR_REQ_RESULT IS 'Phone proxy request result from the BCO model; reserved and null for current HTH CM/BM onboarding events.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.PHONE_DEFAULT_IND IS 'Default phone proxy indicator from the BCO model; reserved and null for current HTH CM/BM onboarding events.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.ELECT_ADD IS 'Electronic-address proxy from the BCO model; reserved and null for current HTH CM/BM onboarding events.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.ELECT_ADD_ACCT_NBR IS 'Account linked to the electronic-address proxy from the BCO model; reserved and null for current HTH CM/BM onboarding events.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.ELECT_ADD_REQ_RESULT IS 'Electronic-address proxy request result from the BCO model; reserved and null for current HTH CM/BM onboarding events.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.ELECT_ADD_DEFAULT_IND IS 'Default electronic-address proxy indicator from the BCO model; reserved and null for current HTH CM/BM onboarding events.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.FPS_ID IS 'FPS proxy identifier from the BCO model; reserved and null for current HTH CM/BM onboarding events.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.FPS_ACCT_NBR IS 'Account linked to the FPS proxy from the BCO model; reserved and null for current HTH CM/BM onboarding events.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.FPS_REQ_RESULT IS 'FPS proxy request result from the BCO model; reserved and null for current HTH CM/BM onboarding events.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.DEBIT_ACCT_NBR IS 'Debit account number from the BCO model; reserved and null for current HTH CM/BM onboarding events.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.EVENT_CCY_CODE IS 'Event currency code from the BCO model; reserved and null for current HTH CM/BM onboarding events.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.EVENT_AMT IS 'Event amount from the BCO model; reserved and null for current HTH CM/BM onboarding events.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.FEE_CHRG_AMT IS 'Fee charged amount from the BCO model; reserved and null for current HTH CM/BM onboarding events.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.FEE_CCY_CODE IS 'Fee currency code from the BCO model; reserved and null for current HTH CM/BM onboarding events.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.TRF_DTE IS 'Transfer date from the BCO model; reserved and null for current HTH CM/BM onboarding events.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.TRF_FREQ IS 'Transfer frequency from the BCO model; reserved and null for current HTH CM/BM onboarding events.';
COMMENT ON COLUMN HTH_BEA.HTH_CRM_EVENT_DETAILS.PROXY_ID_TYPE IS 'Payment proxy identifier type from the BCO model; reserved and null for current HTH CM/BM onboarding events.';
